import re
import uuid
from datetime import datetime, timezone

_ALLOWED_CONTENT_TYPES = frozenset({"image/jpeg", "image/png"})
_MAX_BYTES = 5 * 1024 * 1024
_MAX_EXPIRES = 3600


def init_db(conn):
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            s3_key TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
        """
    )
    conn.commit()


def save_photo_metadata(conn, title, description, s3_key):
    uploaded_at = datetime.now(timezone.utc).isoformat()
    cur = conn.execute(
        "INSERT INTO photos (title, description, s3_key, uploaded_at) "
        "VALUES (?, ?, ?, ?)",
        (title, description, s3_key, uploaded_at),
    )
    row_id = cur.lastrowid
    conn.commit()
    return int(row_id)


def _escape_like(term):
    # Escape the LIKE wildcards and the escape character itself.
    return (
        term.replace("\\", "\\\\")
        .replace("%", "\\%")
        .replace("_", "\\_")
    )


def search_photos(conn, term):
    if not isinstance(term, str):
        raise TypeError("term must be a string")
    # LIKE with a bound pattern and explicit ESCAPE avoids SQL injection and
    # treats %, _ and \ in the user's term as literal characters.
    # Note: SQLite's LIKE is case-insensitive for ASCII characters.
    pattern = "%" + _escape_like(term) + "%"
    cur = conn.execute(
        "SELECT id, title, description, s3_key, uploaded_at FROM photos "
        "WHERE title LIKE ? ESCAPE '\\' OR description LIKE ? ESCAPE '\\' "
        "ORDER BY id ASC",
        (pattern, pattern),
    )
    return [
        {
            "id": row[0],
            "title": row[1],
            "description": row[2],
            "s3_key": row[3],
            "uploaded_at": row[4],
        }
        for row in cur.fetchall()
    ]


def _safe_name(filename):
    # Remove any directory components, handling both / and \ separators.
    base = re.split(r"[\\/]", str(filename))[-1]
    safe = re.sub(r"[^A-Za-z0-9._-]", "_", base)
    if not safe or set(safe) <= {"."}:
        raise ValueError("filename does not yield a usable name")
    return safe


def upload_photo(s3, bucket, filename, data, content_type):
    if content_type not in _ALLOWED_CONTENT_TYPES:
        raise ValueError("unsupported content type")
    if len(data) > _MAX_BYTES:
        raise ValueError("photo exceeds 5 MiB limit")

    safe = _safe_name(filename)
    key = "photos/" + uuid.uuid4().hex + "/" + safe
    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)
    return key


def photo_url(s3, bucket, key, expires=3600):
    if (
        isinstance(expires, bool)
        or not isinstance(expires, int)
        or not (1 <= expires <= _MAX_EXPIRES)
    ):
        raise ValueError("expires must be an integer between 1 and 3600")
    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expires,
    )


def handle_upload(conn, s3, bucket, title, description, filename, data, content_type):
    key = upload_photo(s3, bucket, filename, data, content_type)
    try:
        return save_photo_metadata(conn, title, description, key)
    except Exception:
        # Roll back the uploaded object so no orphan is left behind.
        try:
            s3.delete_object(Bucket=bucket, Key=key)
        except Exception:
            # Cleanup failure must not mask the original error.
            pass
        raise
